import React, { useEffect, useState } from 'react';
import axios from 'axios';

interface JobSeeker {
    id: number;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    gender:string;
    hobbie:string[];
}

const JobSeekers: React.FC = () => {
    const [jobSeekers, setJobSeekers] = useState<JobSeeker[]>([]);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchJobSeekers = async () => {
            try {
                const response = await axios.get('http://localhost:8000/app/jobSeekers', {
                    headers: {
                        Authorization: `Bearer ${localStorage.getItem('token')}`
                    }
                });
                setJobSeekers(response.data);
            } catch (err) {
                console.error('Error fetching job seekers:', err);
                setError('Failed to fetch job seekers');
            } finally {
                setLoading(false);
            }
        };

        fetchJobSeekers();
    }, []);

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seekers</h1>
            <div className="card p-4 mt-3">
                <table className="table">
                    <thead>
                        <tr>
                            <th>ID</th>
                            <th>First Name</th>
                            <th>Last Name</th>
                            <th>Email</th>
                            <th>Phone</th>
                            <th>Gender</th>
                            <th>Hobbies</th>
                        </tr>
                    </thead>
                    <tbody>
                        {jobSeekers.map(seeker => (
                            <tr key={seeker.id}>
                                <td>{seeker.id}</td>
                                <td>{seeker.firstName}</td>
                                <td>{seeker.lastName}</td>
                                <td>{seeker.email}</td>
                                <td>{seeker.phone}</td>
                                <td>{seeker.gender}</td>
                                <td>{seeker.hobbie}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default JobSeekers;
